'use client';

import { ArrowRight, Check, Globe, Sparkles } from 'lucide-react';
import Link from 'next/link';
import { useMemo } from 'react';

import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';

import { ReadinessRing } from './ReadinessRing';
import { getReadinessBarTheme, getReadinessTier } from './profileReadinessTheme';

type ProfileStatusBarProps = {
  bookingSlug: string | null;
  readinessScore: number;
  readinessStageLabel: string;
  completedCount: number;
  totalCount: number;
  requiredRemainingCount: number;
  nextActionLabel: string | null;
  nextActionDescription: string;
  googleHint: string | null;
  googleHref: string;
  onJumpToBooking: () => void;
  onJumpToNextAction: (() => void) | null;
};

export function ProfileStatusBar({
  bookingSlug,
  readinessScore,
  readinessStageLabel,
  completedCount,
  totalCount,
  requiredRemainingCount,
  nextActionLabel,
  nextActionDescription,
  googleHint,
  googleHref,
  onJumpToBooking,
  onJumpToNextAction,
}: ProfileStatusBarProps) {
  const hasBookingSlug = typeof bookingSlug === 'string' && bookingSlug.trim().length > 0;
  const canJumpToNextAction = Boolean(nextActionLabel && onJumpToNextAction);
  const tier = useMemo(() => getReadinessTier(readinessScore), [readinessScore]);
  const theme = useMemo(() => getReadinessBarTheme(tier), [tier]);

  const requiredCopy =
    requiredRemainingCount > 0
      ? `${requiredRemainingCount} action${requiredRemainingCount === 1 ? '' : 's'} required`
      : 'All prerequisites complete';

  return (
    <section
      className={cn(
        'relative flex w-full flex-col items-stretch justify-between gap-5 rounded-2xl border bg-card p-5 transition-all duration-300 md:flex-row md:items-center md:gap-6 md:p-6',
        theme.shell,
      )}
      style={{ boxShadow: `inset 0 1px 0 hsl(var(--background) / 0.65), 0 10px 40px -12px ${theme.glow}` }}
    >
      <div className="flex w-full min-w-0 flex-col items-center gap-5 sm:flex-row sm:items-start md:w-auto">
        <div className="shrink-0">
          <ReadinessRing
            value={readinessScore}
            completed={completedCount}
            total={totalCount}
            size={82}
            stroke={6.5}
          />
        </div>

        <div className="flex min-w-0 flex-col gap-2 text-center sm:text-left">
          <div className="flex flex-wrap items-center justify-center gap-2.5 sm:justify-start">
            <span
              className={cn(
                'rounded border px-2.5 py-0.5 text-[9px] font-extrabold uppercase tracking-widest',
                theme.badge,
              )}
            >
              {readinessStageLabel}
            </span>

            <span className="inline-flex items-center gap-1.5 text-xs font-semibold text-muted-foreground">
              {requiredRemainingCount > 0 ? (
                <span className="relative flex h-1.5 w-1.5" aria-hidden>
                  <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-primary opacity-75" />
                  <span className="relative inline-flex h-1.5 w-1.5 rounded-full bg-primary" />
                </span>
              ) : (
                <span
                  className="inline-flex h-4 w-4 items-center justify-center rounded-full border border-success/25 bg-success/10"
                  aria-hidden
                >
                  <Check className="size-2.5 text-success" />
                </span>
              )}
              {requiredCopy}
            </span>
          </div>

          <p className="max-w-xl text-[13px] font-normal leading-relaxed text-foreground/90 md:text-sm">
            {nextActionDescription}
          </p>

          <div className="mt-1 flex flex-wrap items-center justify-center gap-2 sm:justify-start">
            <div className="inline-flex items-center gap-1.5 rounded-full border border-border/70 bg-muted/40 px-2.5 py-1 text-muted-foreground">
              <Globe className="size-3 shrink-0 opacity-70" aria-hidden />
              <span className="font-mono text-[10px] tracking-wide">
                {hasBookingSlug ? `/${bookingSlug}` : 'Missing booking path'}
              </span>
            </div>

            {googleHint ? (
              <div className="inline-flex max-w-full items-center gap-1.5 rounded-full border border-border/70 bg-muted/40 px-2.5 py-1 text-muted-foreground">
                <span
                  className="inline-flex size-3.5 shrink-0 items-center justify-center rounded-full border border-primary/25 bg-primary/10 text-[8px] font-black text-primary"
                  aria-hidden
                >
                  G
                </span>
                <span className="truncate text-[11px]">{googleHint}</span>
              </div>
            ) : null}
          </div>
        </div>
      </div>

      <div className="flex w-full shrink-0 flex-col items-stretch gap-2 sm:flex-row sm:items-center sm:justify-center md:w-auto md:justify-end">
        {canJumpToNextAction ? (
          <Button
            type="button"
            size="sm"
            className="group h-9 rounded-md px-4 text-xs font-semibold shadow-md"
            onClick={onJumpToNextAction ?? undefined}
          >
            {nextActionLabel}
            <ArrowRight className="size-3.5 transition-transform duration-200 group-hover:translate-x-0.5" />
          </Button>
        ) : hasBookingSlug ? (
          <Button type="button" variant="outline" size="sm" className="h-9 px-4 text-xs font-semibold" onClick={onJumpToBooking}>
            Review booking URL
          </Button>
        ) : (
          <Button type="button" size="sm" className="h-9 px-4 text-xs font-semibold shadow-md" onClick={onJumpToBooking}>
            <Sparkles className="size-3.5 text-warning" aria-hidden />
            Add booking URL
          </Button>
        )}

        {googleHint ? (
          <Button type="button" variant="ghost" size="sm" className="h-9 px-3 text-xs font-semibold text-muted-foreground" asChild>
            <Link href={googleHref}>Link Google</Link>
          </Button>
        ) : null}
      </div>
    </section>
  );
}

'use client';

import { useMemo } from 'react';

import { cn } from '@/lib/utils';

import { getReadinessRingTheme, getReadinessTier } from './profileReadinessTheme';

type ReadinessRingProps = {
  /** Percent complete, 0-100. */
  value: number;
  /** Total items represented (for the inner caption). */
  total: number;
  /** Items completed (for the inner caption). */
  completed: number;
  /** Pixel size of the ring; default 82. */
  size?: number;
  /** Stroke width in pixels; default 6.5. */
  stroke?: number;
  className?: string;
};

/**
 * Circular completion gauge for the profile status bar. Uses non-punitive
 * palettes: warning → primary → success as completion rises.
 */
export function ReadinessRing({
  value,
  total,
  completed,
  size = 82,
  stroke = 6.5,
  className,
}: ReadinessRingProps) {
  const safeValue = Math.min(Math.max(Number.isFinite(value) ? value : 0, 0), 100);
  const radius = (size - stroke) / 2;
  const circumference = 2 * Math.PI * radius;
  const offset = circumference - (safeValue / 100) * circumference;
  const theme = useMemo(
    () => getReadinessRingTheme(getReadinessTier(safeValue)),
    [safeValue],
  );

  return (
    <div
      role="img"
      aria-label={`Profile readiness ${Math.round(safeValue)}%, ${completed} of ${total} fields complete`}
      className={cn(
        'relative inline-flex items-center justify-center motion-safe:transition-transform motion-safe:duration-300 motion-safe:hover:scale-[1.03]',
        className,
      )}
      style={{ width: size, height: size, filter: `drop-shadow(0 0 8px ${theme.glow})` }}
    >
      <svg
        width={size}
        height={size}
        viewBox={`0 0 ${size} ${size}`}
        aria-hidden
        className="-rotate-90 select-none"
      >
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          stroke="currentColor"
          strokeWidth={stroke}
          fill="none"
          className={cn('transition-colors duration-300', theme.track)}
        />
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          stroke="currentColor"
          strokeWidth={stroke}
          strokeLinecap="round"
          fill="none"
          strokeDasharray={circumference}
          strokeDashoffset={offset}
          className={cn(
            'transition-[stroke-dashoffset] duration-700 ease-out',
            theme.stroke,
          )}
        />
      </svg>
      <div className="absolute inset-0 flex flex-col items-center justify-center select-none" aria-hidden>
        <span
          className={cn(
            'text-lg font-bold tabular-nums leading-none tracking-tight',
            theme.text,
          )}
        >
          {Math.round(safeValue)}
          <span className="ml-0.5 text-[10px] font-semibold">%</span>
        </span>
        <span className="mt-1 text-[8px] font-bold uppercase tracking-widest text-muted-foreground">
          {completed}/{total}
        </span>
      </div>
    </div>
  );
}

'use client';

import { ProfileSectionBody } from './ProfileSectionBody';
import { ProfileSectionPane } from './ProfileSectionPane';
import { PROFILE_SECTION_DEFINITIONS } from './profileSections';
import { ProfileShell } from './ProfileShell';
import { ProfileStatusBar } from './ProfileStatusBar';
import { UnifiedActionBar } from './UnifiedActionBar';

import type { deriveProfileVerification } from '../google-business-profile/googleBusinessProfileVerification';
import type { RestaurantLogoUploader } from '../RestaurantLogoUploader';
import type {
  ProfileDirtyKey,
  ProfileDirtySection,
  ReadinessItemKey,
} from '../restaurantProfileModel';
import type { RestaurantSettingsCommandRailItem } from '../shared';
import type { ProfileSectionDefinition, ProfileSectionId } from './profileSections';
import type {
  RestaurantDetailsDraftValues,
  RestaurantDetailsFormValues,
} from '@/components/ops/restaurants/RestaurantDetailsForm';
import type { RestaurantProfile } from '@/services/ops/restaurants';
import type { ComponentProps } from 'react';

type ProfileLoadedViewProps = {
  restaurantId: string;
  railItems: RestaurantSettingsCommandRailItem[];
  activeSectionId: ProfileSectionId;
  activeSection: ProfileSectionDefinition;
  dirtyState: Record<ProfileDirtyKey, boolean>;
  dirtyHandlers: Record<ProfileDirtyKey, (dirty: boolean) => void>;
  draftHandlers: Partial<
    Record<ProfileDirtyKey, (draft: RestaurantDetailsDraftValues, dirty: boolean) => void>
  >;
  dirtyFormSections: readonly (ProfileDirtySection & { formId: string })[];
  discoveryDirty: boolean;
  missingRequiredSectionIds: ReadonlySet<ProfileSectionId>;
  initialValues: RestaurantDetailsFormValues;
  restaurantName: string;
  profile: RestaurantProfile | null | undefined;
  updateMutation: ComponentProps<typeof RestaurantLogoUploader>['updateMutation'];
  isLoading: boolean;
  onLogoPreviewChange: (previewUrl: string | null | undefined) => void;
  onResetDraftChange: (key: ProfileDirtyKey, resetDraft: (() => void) | null) => void;
  gbpFieldVerifications: ReturnType<typeof deriveProfileVerification>['fields'];
  bookingSlug: string | null;
  readinessScore: number;
  readinessStageLabel: string;
  completedCount: number;
  totalCount: number;
  requiredRemainingCount: number;
  googleHint: string | null;
  googleHref: string;
  nextActionLabel: string | null;
  nextActionDescription: string;
  nextReadinessItemKey: ReadinessItemKey | null;
  onFocusReadinessItem: (key: ReadinessItemKey) => void;
  onSaveAll: () => void;
  onCancelActive: () => void;
  gbpDriftCount: number;
  onCompareWithGoogle?: () => void;
};

export function ProfileLoadedView({
  restaurantId,
  railItems,
  activeSectionId,
  activeSection,
  dirtyState,
  dirtyHandlers,
  draftHandlers,
  dirtyFormSections,
  discoveryDirty,
  missingRequiredSectionIds,
  initialValues,
  restaurantName,
  profile,
  updateMutation,
  isLoading,
  onLogoPreviewChange,
  onResetDraftChange,
  gbpFieldVerifications,
  bookingSlug,
  readinessScore,
  readinessStageLabel,
  completedCount,
  totalCount,
  requiredRemainingCount,
  googleHint,
  googleHref,
  nextActionLabel,
  nextActionDescription,
  nextReadinessItemKey,
  onFocusReadinessItem,
  onSaveAll,
  onCancelActive,
  gbpDriftCount,
  onCompareWithGoogle,
}: ProfileLoadedViewProps) {
  return (
    <ProfileShell railItems={railItems}>
      <div className="flex flex-col gap-4">
        <ProfileStatusBar
          bookingSlug={bookingSlug}
          readinessScore={readinessScore}
          readinessStageLabel={readinessStageLabel}
          completedCount={completedCount}
          totalCount={totalCount}
          requiredRemainingCount={requiredRemainingCount}
          googleHint={googleHint}
          googleHref={googleHref}
          nextActionLabel={nextActionLabel}
          nextActionDescription={nextActionDescription}
          onJumpToBooking={() => onFocusReadinessItem('bookingUrl')}
          onJumpToNextAction={
            nextReadinessItemKey ? () => onFocusReadinessItem(nextReadinessItemKey) : null
          }
        />

        {PROFILE_SECTION_DEFINITIONS.map((section) => (
          <ProfileSectionPane
            key={section.id}
            section={section}
            isActive={section.id === activeSectionId}
            isDirty={dirtyState[section.dirtyKey]}
            isMissingRequired={missingRequiredSectionIds.has(section.id)}
          >
            <ProfileSectionBody
              section={section}
              restaurantId={restaurantId}
              restaurantName={restaurantName}
              logoUrl={profile?.logoUrl ?? null}
              updateMutation={updateMutation}
              isLoading={isLoading}
              onLogoPreviewChange={onLogoPreviewChange}
              initialValues={initialValues}
              dirtyHandlers={dirtyHandlers}
              draftHandlers={draftHandlers}
              onResetDraftChange={onResetDraftChange}
              gbpFieldVerifications={gbpFieldVerifications}
            />
          </ProfileSectionPane>
        ))}

        <UnifiedActionBar
          dirtyFormSections={dirtyFormSections}
          discoveryDirty={discoveryDirty}
          activeSection={activeSection}
          lastSavedAt={profile?.updatedAt ?? null}
          onSaveAll={onSaveAll}
          onCancelActive={onCancelActive}
          gbpDriftCount={gbpDriftCount}
          onCompareWithGoogle={onCompareWithGoogle}
        />
      </div>
    </ProfileShell>
  );
}

'use client';

import { useCallback, useMemo } from 'react';

import { deriveReadiness, type ReadinessItemKey } from '../../restaurantProfileModel';
import { getProfileReadinessStageLabel } from '../profileReadinessStage';
import { READINESS_FIELD_TARGETS } from '../profileReadinessTargets';
import { PROFILE_SECTION_DEFINITIONS, type ProfileSectionId } from '../profileSections';

import type { RestaurantDetailsFormValues } from '@/components/ops/restaurants/RestaurantDetailsForm';

type UseProfileReadinessInput = {
  previewValues: RestaurantDetailsFormValues;
  previewLogoUrl: string | null;
  setActiveSectionId: (sectionId: ProfileSectionId) => void;
};

export function useProfileReadiness({
  previewValues,
  previewLogoUrl,
  setActiveSectionId,
}: UseProfileReadinessInput) {
  const readiness = useMemo(
    () => deriveReadiness(previewValues, previewLogoUrl),
    [previewLogoUrl, previewValues],
  );
  const missingRequiredSectionIds = useMemo(() => {
    const ids = new Set<ProfileSectionId>();
    readiness.missingRequired.forEach((item) => {
      const section = PROFILE_SECTION_DEFINITIONS.find(
        (definition) => item.href === `#${definition.legacyHash}`,
      );
      if (section) {
        ids.add(section.id);
      }
    });
    return ids;
  }, [readiness.missingRequired]);
  const readinessStageLabel = getProfileReadinessStageLabel(readiness.score);
  const nextReadinessItem = readiness.missingRequired[0] ?? null;
  const handleFocusReadinessItem = useCallback(
    (key: ReadinessItemKey) => {
      const target = READINESS_FIELD_TARGETS[key];
      if (!target) {
        return;
      }

      setActiveSectionId(target.sectionId);
      requestAnimationFrame(() => {
        const field = document.getElementById(target.fieldId);
        if (field instanceof HTMLElement) {
          field.focus({ preventScroll: true });
          if (typeof field.animate === 'function') {
            field.animate(
              [
                { boxShadow: '0 0 0 0 hsl(var(--primary) / 0)' },
                { boxShadow: '0 0 0 4px hsl(var(--primary) / 0.24)' },
                { boxShadow: '0 0 0 0 hsl(var(--primary) / 0)' },
              ],
              { duration: 900, easing: 'cubic-bezier(0.2, 0, 0, 1)' },
            );
          }
        }
      });
    },
    [setActiveSectionId],
  );

  return {
    readiness,
    missingRequiredSectionIds,
    readinessStageLabel,
    nextReadinessItem,
    handleFocusReadinessItem,
  };
}

export function getProfileReadinessStageLabel(score: number) {
  if (score >= 90) {
    return 'Launch-ready';
  }
  if (score >= 70) {
    return 'Almost ready';
  }
  if (score >= 40) {
    return 'In progress';
  }
  return 'Needs setup';
}

export type ReadinessTier = 'setup' | 'progress' | 'ready';

export function getReadinessTier(score: number): ReadinessTier {
  if (score >= 90) return 'ready';
  if (score >= 60) return 'progress';
  return 'setup';
}

export function getReadinessRingTheme(tier: ReadinessTier) {
  switch (tier) {
    case 'ready':
      return {
        stroke: 'text-success',
        track: 'text-success/15',
        text: 'text-success',
        glow: 'hsl(var(--success) / 0.22)',
      };
    case 'progress':
      return {
        stroke: 'text-primary',
        track: 'text-primary/15',
        text: 'text-primary',
        glow: 'hsl(var(--primary) / 0.28)',
      };
    default:
      return {
        stroke: 'text-warning',
        track: 'text-warning/15',
        text: 'text-warning',
        glow: 'hsl(var(--warning) / 0.22)',
      };
  }
}

export function getReadinessBarTheme(tier: ReadinessTier) {
  switch (tier) {
    case 'ready':
      return {
        shell:
          'border-success/25 bg-gradient-to-r from-success/[0.07] via-card to-card shadow-[inset_0_1px_0_hsl(var(--background)/0.65),0_10px_32px_-14px_hsl(var(--success)/0.35)]',
        badge: 'border-success/25 bg-success/10 text-success',
        glow: 'hsl(var(--success) / 0.05)',
      };
    case 'progress':
      return {
        shell:
          'border-primary/25 bg-gradient-to-r from-primary/[0.07] via-card to-card shadow-[inset_0_1px_0_hsl(var(--background)/0.65),0_10px_32px_-14px_hsl(var(--primary)/0.28)]',
        badge: 'border-primary/25 bg-primary/10 text-primary',
        glow: 'hsl(var(--primary) / 0.05)',
      };
    default:
      return {
        shell:
          'border-warning/25 bg-gradient-to-r from-warning/[0.07] via-card to-card shadow-[inset_0_1px_0_hsl(var(--background)/0.65),0_10px_32px_-14px_hsl(var(--warning)/0.28)]',
        badge: 'border-warning/25 bg-warning/10 text-warning',
        glow: 'hsl(var(--warning) / 0.05)',
      };
  }
}

